ALTER TABLE "waha_servers" ADD CONSTRAINT "waha_servers_base_url_check" CHECK ("waha_servers"."base_url" ~ '^https://[a-z0-9.-]+(:[1-9][0-9]{0,4})?(/[!-~]*)?$' AND "waha_servers"."base_url_host" = substring("waha_servers"."base_url" from '^https://([^/]+)') AND "waha_servers"."base_url_host" !~ ':443$' AND coalesce(substring("waha_servers"."base_url_host" from ':([0-9]+)$')::integer, 443) <= 65535);--> statement-breakpoint
ALTER TABLE "settings_secrets" ADD CONSTRAINT "settings_secrets_binding_check" CHECK (("settings_secrets"."scope" = 'conversions') = ("settings_secrets"."adnet_id" IS NOT NULL) AND ("settings_secrets"."scope" <> 'conversions' OR "settings_secrets"."bound_host" IS NOT NULL));